def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive_opponents = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if budget <= 0:
        return 0.0

    if not alive_opponents:
        if hp <= 2 or no_water >= 1:
            return float(min(budget, DAILY_SALARY * 0.9))
        return float(min(budget, DAILY_SALARY * 0.2))

    units = supply / float(WATER_REQ)
    tight = units < (1 + len(alive_opponents) * 0.55)
    very_tight = units < (1 + len(alive_opponents) * 0.4)
    abundant = units >= (1 + len(alive_opponents) * 0.9)

    prev_bids = []
    urgent_opp = 0
    rich_opp = 0
    for opp in alive_opponents:
        if opp.get('budget', 0) >= budget:
            rich_opp += 1
        if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
            urgent_opp += 1
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            prev_bids.append(prev.get('bid', 0.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0

    if hp <= 2 or no_water >= 2:
        bid = DAILY_SALARY * 0.98
    elif hp <= 4 or no_water >= 1:
        if very_tight:
            bid = max(DAILY_SALARY * 0.9, highest_prev + 6)
        else:
            bid = max(DAILY_SALARY * 0.78, highest_prev + 2)
    else:
        if very_tight:
            bid = max(DAILY_SALARY * 0.88, highest_prev + 4)
        elif tight:
            bid = max(DAILY_SALARY * 0.68, highest_prev + 1.5)
        elif abundant:
            bid = DAILY_SALARY * 0.26
        else:
            bid = DAILY_SALARY * 0.48

    if urgent_opp >= 1 and not abundant:
        bid += 4
    if rich_opp >= 2 and tight:
        bid += 3
    if day >= 8 and hp <= 5:
        bid += 5

    if abundant and hp >= 6 and no_water == 0:
        bid = min(bid, DAILY_SALARY * 0.4)

    if highest_prev >= DAILY_SALARY * 0.9 and hp >= 5 and no_water == 0 and not very_tight:
        bid = min(bid, DAILY_SALARY * 0.55)

    bid = max(0.0, min(float(budget), float(bid)))
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    # Alive opponents
    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append(o)

    # If alone, bid conservatively but ensure survival
    if not alive_opps:
        return float(min(my_status.get('budget', 0.0), DAILY_SALARY * 0.4))

    # Extract yesterday bids only from previous_trace
    yesterday_bids = []
    for o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                yesterday_bids.append(float(b))
            except Exception:
                pass

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0
    my_hp = float(my_status.get('hp', 0.0))
    my_budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    # Supply pressure: higher supply reduces need to overbid
    # Normalize supply to [0,1]
    if MAX_SUPPLY == MIN_SUPPLY:
        supply_norm = 0.5
    else:
        supply_norm = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
        if supply_norm < 0.0:
            supply_norm = 0.0
        if supply_norm > 1.0:
            supply_norm = 1.0

    # Base target bid: slightly below typical observed bids (~112-118) to win with less burn
    # If supply is low, increase bid.
    base = DAILY_SALARY * (0.50 + (1.0 - supply_norm) * 0.15)  # ~45 to 63

    # React to yesterday highest bid pressure.
    # If someone was willing to pay very high yesterday, we must bid closer to it.
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        # If we're healthy, undercut slightly; if low HP, match more aggressively.
        if my_hp > 3.0:
            target = max(base, highest_prev_bid * 0.85)
        else:
            target = max(base, highest_prev_bid * 0.95)
    else:
        # If yesterday bids were moderate, bid around base and just above to avoid tie losses.
        target = max(base, highest_prev_bid * 0.70 + 5.0)

    # Urgency from no-water days / low HP
    if my_hp <= 2.0 or no_water_days >= 2:
        target *= 1.15

    # Budget safety: never exceed budget; also avoid spending all budget unless forced.
    # Keep a buffer proportional to remaining days (episode is 10; we don't know current day count reliably).
    # Use a simple fraction buffer.
    spend_cap = my_budget * (0.35 if my_hp > 3.0 else 0.65)
    bid = min(my_budget, target, spend_cap if spend_cap > 0 else my_budget)

    # Final clamp to non-negative
    if bid < 0.0:
        bid = 0.0

    return float(bid)

